local function special_bind(key, workspace, command)
    hl.bind(key, function()
        hl.dispatch(hl.dsp.workspace.toggle_special(workspace))

        local windows = hl.get_workspace_windows("special:" .. workspace)

        if #windows == 0 then
            hl.exec_cmd(command)
        end
    end)
end

